            CL_CHECK(clEnqueueNDRangeKernel(queue, kernel, 3, ଖାଲି, global_work_size, local_work_size, 0, ଖାଲି, &evt));
            CL_CHECK(clWaitForEvents(1, &evt));
            CL_CHECK(clReleaseMemObject(data_device));

