        CL_CHECK(clSetKernelArg(kernel, 12, ଆକାର(ପୂର୍ଣ୍ଣସଂଖ୍ୟା),      &ne12));
        CL_CHECK(clSetKernelArg(kernel, 13, ଆକାର(ପୂର୍ଣ୍ଣସଂଖ୍ୟା),      &ne13));
        CL_CHECK(clSetKernelArg(kernel, 14, ଆକାର(cl_ulong), &nb10));
