        CL_CHECK(clSetKernelArg(kernel, 17, ଆକାର(cl_ulong), &nb13));
        CL_CHECK(clSetKernelArg(kernel, 18, ଆକାର(ପୂର୍ଣ୍ଣସଂଖ୍ୟା),      &ne0));
        CL_CHECK(clSetKernelArg(kernel, 19, ଆକାର(cl_ulong), &nb0));
